import { SvelteMap } from 'svelte/reactivity'

const syncStore = new SvelteMap()

export function getEntry(id) {
  return syncStore.get(id)
}

export function setEntry(id, value) {
  return syncStore.set(id, value)
}

export function mergeEntry(id, value) {
  const entry = getEntry(id)
  if (!entry) return setEntry(id, value)
  return syncStore.set(id, { ...entry, ...value })
}

export function removeEntry(id) {
  return syncStore.delete(id)
}
